// 환경변수에서 채널 ID 목록 파싱
// YOUTUBE_CHANNEL_IDS: 콤마 구분 채널ID (또는 채널ID:노트북ID 형태)
// 예: UCxxxxxx,UCyyyyyy
// 또는 다중 노트북: UCxxxxxx:notebook_id_1,UCyyyyyy:notebook_id_2
const raw = $env.YOUTUBE_CHANNEL_IDS || '';
const entries = raw.split(',').map(e => e.trim()).filter(Boolean);

const channels = entries.map(entry => {
  const [channelId, notebookId] = entry.split(':');
  return { channelId: channelId.trim(), notebookId: (notebookId || '').trim() };
});

return channels.map(ch => ({ json: ch }));

// RSS XML 파싱: 최근 1.5시간 이내 업로드 영상만 추출
const xml = $input.item.json.data || '';
const channelId = $input.item.json.channelId || '';
const notebookId = $input.item.json.notebookId || '';

// 간단 XML 파싱 (n8n Code 노드에서 DOMParser 미지원 → regex 사용)
const entries = [];
const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
let match;

while ((match = entryRegex.exec(xml)) !== null) {
  const block = match[1];
  const videoId = (block.match(/<yt:videoId>([^<]+)<\/yt:videoId>/) || [])[1];
  const title = (block.match(/<title>([^<]+)<\/title>/) || [])[1] || '';
  const published = (block.match(/<published>([^<]+)<\/published>/) || [])[1] || '';

  if (!videoId) continue;

  const publishedMs = new Date(published).getTime();
  const cutoffMs = Date.now() - 90 * 60 * 1000; // 1.5시간 이내

  if (publishedMs >= cutoffMs) {
    entries.push({
      videoUrl: `https://www.youtube.com/watch?v=${videoId}`,
      title: title.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>'),
      publishedAt: published,
      channelId,
      notebookId,
    });
  }
}

if (entries.length === 0) {
  return [{ json: { skip: true, channelId, reason: '새 영상 없음' } }];
}

return entries.map(e => ({ json: e }));

// 결과 로깅
const result = $input.item.json;
const videoUrl = $input.item.json.source_url || '';

if (result.duplicate) {
  console.log(`[WF-09] 중복 건너뜀: ${videoUrl}`);
} else if (result.added) {
  console.log(`[WF-09] 소스 추가 완료: ${videoUrl} (cleaned=${result.cleaned_up})`);
} else if (result.error) {
  console.error(`[WF-09] 소스 추가 실패: ${result.error}`);
}

return [{ json: result }];
